<style>
.dam-card{padding:22px 22px 18px}.dam-title{margin:0 0 16px;font-size:1.5rem;font-weight:800;color:#10223f}
.dam-toolbar{display:flex;gap:14px;align-items:end;flex-wrap:wrap;margin-bottom:16px}.dam-field{display:flex;flex-direction:column;gap:6px;min-width:220px;flex:1 1 220px}
.dam-field label{font-weight:700;color:#334155;font-size:.92rem}.dam-actions{display:flex;gap:10px;flex-wrap:wrap}.dam-grid{display:grid;grid-template-columns:repeat(4,minmax(180px,1fr));gap:14px}.dam-metric{background:#fff;border:1px solid #e5e7eb;border-radius:18px;padding:14px;box-shadow:0 8px 24px rgba(15,23,42,.04)}
.dam-metric__label{font-size:.82rem;color:#64748b}.dam-metric__value{font-size:1.25rem;font-weight:800;color:#0f172a;word-break:break-word}.dam-table-wrap{overflow:auto;border:1px solid #e5e7eb;border-radius:14px;background:#fff}.dam-table{width:100%;border-collapse:collapse}.dam-table th,.dam-table td{padding:.72rem .78rem;border-bottom:1px solid #e5e7eb;vertical-align:top;text-align:left}.dam-table thead th{background:#f8fafc;font-weight:800;color:#0f172a;position:sticky;top:0;z-index:1}.dam-tabs{display:flex;gap:10px;flex-wrap:wrap;margin-top:14px}.dam-tab{display:inline-flex;align-items:center;gap:6px;padding:.55rem .9rem;border-radius:999px;background:#eef2ff;color:#1e3a8a;text-decoration:none;font-weight:700}.dam-tab.is-active{background:#1d4ed8;color:#fff}.dam-meta{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:12px}.dam-chip{display:inline-flex;align-items:center;border-radius:999px;padding:.28rem .7rem;font-size:.82rem;font-weight:700;background:#eef2ff;color:#1e3a8a}.dam-note{background:#fff7e6;color:#9a6700;border-radius:14px;padding:12px 14px;margin-bottom:12px}.dam-empty{padding:18px;border:1px dashed #cbd5e1;border-radius:14px;color:#64748b;background:#fff}@media (max-width:1100px){.dam-grid{grid-template-columns:repeat(2,minmax(180px,1fr));}}@media (max-width:700px){.dam-grid{grid-template-columns:1fr;}}</style>

<style>
.dam-chart-shell{margin:14px 0 16px;padding:14px;border:1px solid #e5e7eb;border-radius:14px;background:#fff}
.dam-chart-top{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:10px}
.dam-chart-buttons{display:flex;gap:8px;flex-wrap:wrap}
.dam-chart-btn{border:1px solid #cbd5e1;background:#fff;color:#1e3a8a;padding:.45rem .8rem;border-radius:999px;font-weight:700;cursor:pointer}
.dam-chart-btn.is-active{background:#1d4ed8;color:#fff;border-color:#1d4ed8}
.dam-canvas-wrap{position:relative;height:300px}
</style>
<script src="https://cdn.jsdelivr.net/npm/chart.js"></script>
